// The version has one source: opal/corelib/version.mjs. The compiler's
// VERSION (its "Generated by Opal" banner and --version), the corelib's
// RUBY_ENGINE_VERSION and Opal::VERSION must all answer that one value, and
// no other file may write a version literal of its own.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { VERSION } from "../../../lib/opal/compiler/index.mjs";

const root = new URL("../../../", import.meta.url);

test("VERSION answers opal/corelib/version.mjs", () => {
  const src = readFileSync(new URL("opal/corelib/version.mjs", root), "utf8");
  assert.equal(VERSION, /OPAL_VERSION = "([^"]+)"/.exec(src)[1]);
});

test("no other version literal is written in the tree", () => {
  const constants = readFileSync(new URL("opal/corelib/constants.rb", root), "utf8");
  assert.match(constants, /^::RUBY_ENGINE_VERSION = `Opal\.esm\["corelib\/version"\]\.OPAL_VERSION`$/m);
  const versionRb = readFileSync(new URL("stdlib/opal/version.rb", root), "utf8");
  assert.match(versionRb, /VERSION = ::RUBY_ENGINE_VERSION/);
  // the banner and --version read lib/opal/compiler/version.mjs, which is a
  // re-export, not a literal:
  const compilerVersion = readFileSync(new URL("lib/opal/compiler/version.mjs", root), "utf8");
  assert.match(compilerVersion, /export \{ OPAL_VERSION as VERSION \} from "\.\.\/\.\.\/\.\.\/opal\/corelib\/version\.mjs";/);
});

test("the runtime answers the version", () => {
  // the probe runs Ruby: exe/opal is compiler-only, so this reads the
  // runtime through drill, rebuilt to a private tmp/ OUT (the parallel
  // spec-file trap: no two rebuilds may truncate one tracked exe)
  const out = join(fileURLToPath(root), `tmp/opal-drill-version-${process.pid}`);
  const build = spawnSync(process.execPath, [fileURLToPath(new URL("tasks/drill.mjs", root))], { encoding: "utf8", env: { ...process.env, OUT: `tmp/opal-drill-version-${process.pid}` } });
  assert.equal(build.status, 0, build.stderr);
  const probe = 'print RUBY_ENGINE_VERSION, "|"; require "opal/version"; print Opal::VERSION';
  const run = spawnSync(process.execPath, [out, "--no-cache", "-e", probe], { encoding: "utf8" });
  assert.equal(run.status, 0, run.stderr);
  assert.equal(run.stdout, `${VERSION}|${VERSION}`);
});
